package dev.lain.claudejb.session

/**
 * Tells the user's own words apart from the binary's, inside a `user` line of a session transcript.
 *
 * **The bug this exists for.** Restoring a conversation showed, attributed to the user and styled as their
 * prompt, things they never typed: `<local-command-caveat>Caveat: The messages below were generated by the
 * user while running local commands. DO NOT respond to these…`, `<command-name>/compact</command-name>`,
 * `<task-notification>…`, and another agent's message wrapped in `<agent-message from="…">`. They arrive as
 * ordinary `text` blocks on a `user` line, so the reader — which mapped every such block to a USER row —
 * could not tell them apart. Reading your own transcript back and finding paragraphs you never wrote is the
 * kind of defect that makes the whole view untrustworthy.
 *
 * **The tag set is closed, and deliberately so.** Only the wrappers the binary is known to emit are treated
 * as synthetic (inventoried from real transcripts: `task-notification`, `local-command-caveat`,
 * `command-name`, `command-message`, `local-command-stdout`, `agent-message`, `cross-session-message`). A
 * generic "anything starting with a tag is not the user" rule would silently eat a prompt that legitimately
 * starts with XML — and someone pasting markup into a chat about markup is not an edge case here.
 *
 * **An inter-agent message wears two disguises.** Its wrapper carries attributes (`from`, `from-name`), so
 * a matcher demanding `>` straight after the tag name never sees it; and the line may open with one of a
 * fixed set of preamble sentences before the wrapper. Both are recognised, by one pass: the preamble only
 * moves where the wrapper is looked for, and a wrapper only counts when it LEADS, so a single decision
 * decides what a block is and text that merely contains such a string stays the user's, whole and unedited.
 * That asymmetry is deliberate — mistaking the binary for the user shows a paragraph in the wrong colour,
 * while mistaking the user for the binary hides something they really wrote.
 *
 * Pure and side-effect free, so the rules are testable without a session, a file or an IDE.
 */
internal object SyntheticUserText {

    /** What a `user` line's text block turns out to be. */
    sealed interface Kind {
        /** The user's own words: rendered as their prompt, unchanged. */
        data class Prompt(val text: String) : Kind

        /** A slash command they ran (`/compact`): still theirs, shown the way they typed it. */
        data class Command(val text: String) : Kind

        /** The binary talking: rendered as a system note, the same as the live path does. */
        data class SystemNote(val text: String) : Kind

        /** Internal scaffolding with nothing to show — dropped. */
        data object Hidden : Kind
    }

    /**
     * Classifies one `text` block. [isMeta] is the line's own `isMeta` flag, which the binary sets on the
     * scaffolding it injects; it is honoured because it is the binary's own statement about the line, and it
     * catches wrappers this list has not met yet.
     */
    fun classify(text: String, isMeta: Boolean = false): Kind {
        val body = text.trim()
        if (body.isEmpty()) return Kind.Hidden
        // The wrapper is looked for past a preamble, but [body] — the trimmed original — is what falls
        // through: nothing is stripped from a prompt that turns out to be the user's after all. And the
        // binary's own [isMeta] flag is believed only once no wrapper has matched, so a `/compact` on a meta
        // line is still shown as the command the user typed.
        return syntheticKind(withoutPreamble(body)) ?: if (isMeta) Kind.Hidden else Kind.Prompt(body)
    }

    /**
     * The closed tag set, as one function: what a block is when it LEADS with a wrapper the binary is known to
     * emit, and `null` when it does not — which is the answer for every prompt that merely happens to start
     * with markup, and for a wrapper this list has not met yet.
     */
    private fun syntheticKind(body: String): Kind? = when (leadingTag(body)) {
        // A `/compact` the user ran: their action, so it stays theirs — shown as the command they typed
        // rather than as the three XML blocks the binary records it in.
        COMMAND_NAME, COMMAND_MESSAGE -> commandOf(body)?.let(Kind::Command) ?: Kind.Hidden

        // The binary's own voice. The live path renders these as system notices, so a restored
        // transcript renders them the same way instead of putting them in the user's mouth.
        LOCAL_COMMAND_STDOUT -> inner(body, LOCAL_COMMAND_STDOUT)?.let(Kind::SystemNote) ?: Kind.Hidden

        TASK_NOTIFICATION -> taskNotice(body)?.let(Kind::SystemNote) ?: Kind.Hidden

        // Another agent talking. It reaches the transcript on a `user` line and reads like a prompt,
        // which is exactly what makes it worth naming: the sender is not the person at the keyboard.
        AGENT_MESSAGE, CROSS_SESSION_MESSAGE -> agentMessage(body)?.let(Kind::SystemNote) ?: Kind.Hidden

        // An instruction aimed at the model, never at the reader.
        LOCAL_COMMAND_CAVEAT -> Kind.Hidden

        else -> null
    }

    /** `<command-name>/compact</command-name> … <command-args>x</command-args>` → `/compact x`. */
    private fun commandOf(body: String): String? {
        val name = inner(body, COMMAND_NAME) ?: inner(body, COMMAND_MESSAGE) ?: return null
        val args = inner(body, COMMAND_ARGS).orEmpty()
        val command = if (name.startsWith("/")) name else "/$name"
        return listOf(command, args).filter { it.isNotBlank() }.joinToString(" ")
    }

    /**
     * A settled subagent, condensed to its summary — the same shape the live path shows.
     *
     * The raw block carries ids, an output path and a note aimed at the model; none of that is a sentence a
     * human wants in their transcript, and the summary is the one line that says what happened.
     */
    private fun taskNotice(body: String): String? {
        val summary = inner(body, "summary")?.takeIf { it.isNotBlank() } ?: return null
        val status = inner(body, "status")?.takeIf { it.isNotBlank() }
        return if (status == null) summary else "Subagent $status: $summary"
    }

    /**
     * Another agent's message, said to be from whoever sent it.
     *
     * The wrapper is the boundary: the preamble before it and the standing instruction the binary appends
     * after it are both aimed at the model, so taking the inside leaves the message and nothing else —
     * without this having to know those texts. The message is kept whole, because unlike a task
     * notification it has no summary field and every line of it is content someone wrote.
     */
    private fun agentMessage(body: String): String? {
        val message = wrappedBody(body)?.takeIf { it.isNotBlank() } ?: return null
        return "Message from ${senderOf(body)}:\n$message"
    }

    /**
     * What a leading wrapper carries: the text inside it, or everything after it when the wrapper is never
     * closed — a truncated message is still worth reading, and dropping it would lose the only copy. The
     * LAST closing tag ends it, so a body quoting the tag does not cut the message short.
     */
    private fun wrappedBody(body: String): String? {
        val open = LEADING_TAG.find(body) ?: return null
        val rest = body.substring(open.value.length)
        val close = rest.lastIndexOf("</${open.groupValues[1]}>")
        return (if (close < 0) rest else rest.take(close)).trim()
    }

    /** Who sent it. The binary writes both a display name and an address, and prefers the name. */
    private fun senderOf(body: String): String {
        val open = LEADING_TAG.find(body)?.value.orEmpty()
        return attribute(open, "from-name") ?: attribute(open, "from") ?: UNNAMED_SENDER
    }

    /** The value of `name="…"` on an opening tag, whatever order the attributes are written in. */
    private fun attribute(openingTag: String, name: String): String? =
        Regex("\\b$name=\"([^\"]*)\"").find(openingTag)?.groupValues?.get(1)?.trim()?.takeIf { it.isNotEmpty() }

    /**
     * [body] without the sentence the binary puts on the line above an inter-agent wrapper. The set is
     * closed and matched whole, including its newline, so the only text this can shorten is text the binary
     * wrote itself.
     */
    private fun withoutPreamble(body: String): String =
        PREAMBLES.firstOrNull(body::startsWith)?.let { body.substring(it.length) } ?: body

    /** The first `<tag>` of [body], or null when it does not start with one. */
    private fun leadingTag(body: String): String? =
        LEADING_TAG.find(body)?.groupValues?.get(1)

    /** The text inside `<tag>…</tag>`, trimmed; null when the tag is absent. */
    private fun inner(body: String, tag: String): String? =
        Regex("<$tag>(.*?)</$tag>", RegexOption.DOT_MATCHES_ALL).find(body)?.groupValues?.get(1)?.trim()

    /**
     * An opening tag, attributes and all: they follow a space or a tab and the tag closes on the same line,
     * which is the binary's own rule for these wrappers. An inter-agent message needs it — it arrives as
     * `<agent-message from="…">`, and a pattern demanding `>` straight after the name reads it as a prompt.
     */
    private val LEADING_TAG = Regex("^<([a-z][a-z0-9-]*)(?:[ \\t][^>\\r\\n]*)?>")

    private val PREAMBLES = listOf(
        "Another Claude session sent a message while you were working:\n",
        "Another Claude session sent a message:\n",
        "A peer session sent a message while you were working:\n",
    )

    private const val TASK_NOTIFICATION = "task-notification"
    private const val LOCAL_COMMAND_CAVEAT = "local-command-caveat"
    private const val LOCAL_COMMAND_STDOUT = "local-command-stdout"
    private const val COMMAND_NAME = "command-name"
    private const val COMMAND_MESSAGE = "command-message"
    private const val COMMAND_ARGS = "command-args"
    private const val AGENT_MESSAGE = "agent-message"
    private const val CROSS_SESSION_MESSAGE = "cross-session-message"

    /** What an inter-agent message is filed under when its wrapper names no sender. */
    private const val UNNAMED_SENDER = "another agent"
}
